class Solution:
    def longestDecomposition(self, text: str) -> int:
        res, l, r = 0, 0, len(text) - 1
        while l < r:
            found = False
            for ln in range(1, (r - l + 1) // 2 + 1):
                if text[l:l + ln] == text[r - ln + 1:r + 1]:
                    res += 2
                    l += ln
                    r -= ln
                    found = True
                    break
            if not found:
                return res + 1
        return res

