class Solution {
public:
    int longestDecomposition(string text) {
        int res = 0, l = 0, r = text.size() - 1;
        while (l < r) {
            bool found = false;
            int maxLen = (r - l + 1) / 2;
            for (int len = 1; len <= maxLen; ++len) {
                if (text.compare(l, len, text, r - len + 1, len) == 0) {
                    res += 2;
                    l += len;
                    r -= len;
                    found = true;
                    break;
                }
            }
            if (!found) return res + 1;
        }
        return res;
    }
};

