class Solution {
public:
    int longestDecomposition(string text) {
        const long long MOD = (1LL << 61) - 1, B = 131;
        auto mul = [&](long long a, long long b) {
            __int128 c = (__int128)a * b;
            return (long long)(c % MOD);
        };
        int res = 0, l = 0, r = text.size() - 1;
        vector<long long> pw(text.size());
        pw[0] = 1;
        for (int i = 1; i < (int)pw.size(); ++i) pw[i] = mul(pw[i - 1], B);
        while (l < r) {
            long long hf = 0, hb = 0;
            int ln = 0;
            bool matched = false;
            while (l + ln < r - ln + 1) {
                hf = (mul(hf, B) + text[l + ln]) % MOD;
                hb = (hb + mul(text[r - ln], pw[ln])) % MOD;
                ln++;
                if (hf == hb) { res += 2; l += ln; r -= ln; matched = true; break; }
            }
            if (!matched) return res + 1;
        }
        return res;
    }
};

