class Solution {
    public int longestDecomposition(String text) {
        final long MOD = (1L << 61) - 1, B = 131;
        int res = 0, l = 0, r = text.length() - 1;
        long[] pw = new long[text.length()];
        pw[0] = 1;
        for (int i = 1; i < pw.length; i++) pw[i] = pw[i - 1] * B % MOD;
        while (l < r) {
            long hf = 0, hb = 0;
            int ln = 0;
            boolean matched = false;
            while (l + ln < r - ln + 1) {
                hf = (hf * B + text.charAt(l + ln)) % MOD;
                hb = (hb + text.charAt(r - ln) * pw[ln]) % MOD;
                ln++;
                if (hf == hb) { res += 2; l += ln; r -= ln; matched = true; break; }
            }
            if (!matched) return res + 1;
        }
        return res;
    }
}

